void ParabolicEase::setEaseTimes(Real easeInTime, Real easeOutTime, Real duration)
{
	if (duration > 0.0f)
	{
		if (easeInTime > 0.0f)
			easeInTime /= duration;
		else
			easeInTime = 0.0f;

		if (easeOutTime > 0.0f)
			easeOutTime /= duration;
		else
			easeOutTime = 0.0f;
	}

	m_in = easeInTime;
	if (m_in < 0.0f || m_in > 1.0f)
		m_in = clamp(m_in);

	m_out = 1.0f - easeOutTime;
	if (m_out < 0.0f || m_out > 1.0f)
		m_out = clamp(m_out);

	if (m_in > m_out)
		m_in = m_out;
}

